<"'!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Cellular Playground</title>
<style>
  :root { color-scheme: dark; }
  * { box-sizing: border-box; }
  body {
    margin: 0; min-height: 100vh;
    font-family: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
    background: #0d1117; color: #e6edf3;
    display: flex; flex-direction: column; align-items: center;
    padding: 24px 16px;
  }
  h1 { font-size: 20px; letter-spacing: 2px; margin: 0 0 4px; }
  p.sub { margin: 0 0 20px; color: #8b949e; font-size: 12px; }
  .controls {
    display: flex; flex-wrap: wrap; gap: 10px; align-items: center;
    justify-content: center; margin-bottom: 16px;
  }
  button, select, input {
    font: inherit; font-size: 13px;
    background: #161b22; color: #e6edf3;
    border: 1px solid #30363d; border-radius: 6px;
    padding: 6px 12px; cursor: pointer;
  }
  button:hover { background: #1f2733; }
  button.primary { background: #238636; border-color: #2ea043; }
  button.primary:hover { background: #2ea043; }
  select:focus, input:focus, button:focus { outline: 2px solid #58a6ff; }
  canvas {
    background: #010409; border: 1px solid #30363d;
    border-radius: 8px; image-rendering: pixelated; touch-action: none;
  }
  .hint { margin-top: 12px; color: #8b949e; font-size: 12px; text-align: center; }
  .stats { color: #8b949e; font-size: 12px; margin-top: 6px; }
</style>
</head>
<body>
  <h1>CELLULAR PLAYGROUND</h1>
  <p class="sub">an interactive cellular automaton toy</p>

  <div class="controls">
    <button id="play" class="primary">Pause</button>
    <button id="step">Step</button>
    <button id="random">Randomize</button>
    <button id="clear">Clear</button>
    <label>Rule
      <select id="rule">
        <option value="gol">Game of Life</option>
        <option value="highlife">HighLife</option>
        <option value="seeds">Seeds</option>
        <option value="daynight">Day &amp; Night</option>
        <option value="chaos">Chaos</option>
      </select>
    </label>
    <label>Speed <input type="range" id="speed" min="1" max="30" value="12"></label>
  </div>

  <canvas id="c" width="800" height="600"></canvas>
  <div class="stats" id="stats">generation 0</div>
  <div class="hint">click / drag to draw live cells · space to pause · r to randomize · c to clear</div>

<script>
"use strict";
(() => {
  const canvas = document.getElementById("c");
  const ctx = canvas.getContext("2d");
  const N = 8;                       // cell size in px
  const COLS = canvas.width  / N;
  const ROWS = canvas.height / N;

  const $ = (id) => document.getElementById(id);
  const playBtn = $("play"), ruleSel = $("rule"), speed = $("speed"), stats = $("stats");

  let grid = makeGrid();
  let running = true;
  let gen = 0;
  let rule = "gol";

  // Rule: survival / birth sets (8-neighbor counts).
  const RULES = {
    gol:      { s:[2,3], b:[3] },
    highlife: { s:[2,3], b:[3,6] },
    seeds:    { s:[],   b:[2] },
    daynight: { s:[3,4,6,7,8], b:[3,6,7,8] },
    chaos:    { s:[1,3,5,7],   b:[1,3,5,7] },
  };

  function makeGrid() {
    return Array.from({ length: ROWS }, () => new Uint8Array(COLS));
  }

  function countNeighbors(g, r, c) {
    let n = 0;
    for (let dr = -1; dr <= 1; dr++)
      for (let dc = -1; dc <= 1; dc++) {
        if (dr === 0 && dc === 0) continue;
        const rr = (r + dr + ROWS) % ROWS;
        const cc = (c + dc + COLS) % COLS;
        n += g[rr][cc];
      }
    return n;
  }

  function step() {
    const { s, b } = RULES[rule];
    const next = makeGrid();
    for (let r = 0; r < ROWS; r++)
      for (let c = 0; c < COLS; c++) {
        const n = countNeighbors(grid, r, c);
        const alive = grid[r][c] === 1;
        next[r][c] = (alive ? s.includes(n) : b.includes(n)) ? 1 : 0;
      }
    grid = next;
    gen++;
  }

  function randomizeFill(fraction = 0.25) {
    gen = 0;
    for (let r = 0; r < ROWS; r++)
      for (let c = 0; c < COLS; c++)
        grid[r][c] = Math.random() < fraction ? 1 : 0;
  }

  function fillRule(survive, birth, seedFraction) {
    // deterministic pseudo-random "pretty" patterns using the rule itself
    gen = 0;
    grid = makeGrid();
    const { s, b } = { s: survive, b: birth }; // placeholder to keep closure simple
    void s; void b;
    randomizeFill(seedFraction);
  }

  function clearGrid() { gen = 0; grid = makeGrid(); }

  // --- palette per rule ---
  const PALETTES = {
    gol:      (c) => `hsl(160 ${30 + 40 * c}% ${10 + 50 * c}%)`,
    highlife: (c) => `hsl(${280 - 120 * c} 70% ${15 + 45 * c}%)`,
    seeds:    (c) => `hsl(45 ${30 + 40 * c}% ${15 + 50 * c}%)`,
    daynight: (c) => `hsl(210 ${30 + 40 * c}% ${12 + 46 * c}%)`,
    chaos:    (c) => `hsl(${Math.floor(gen * 3 + c * 80) % 360} 80% ${15 + 40 * c}%)`,
  };

  function draw() {
    const palette = PALETTES[rule];
    ctx.fillStyle = "#010409";
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = "#9ecbff";
    for (let r = 0; r < ROWS; r++) {
      const row = grid[r];
      for (let c = 0; c < COLS; c++) {
        const v = row[c];
        if (v) {
          ctx.fillStyle = palette(v);
          ctx.fillRect(c * N, r * N, N, N);
        }
      }
    }
    stats.textContent = `generation ${gen} · ${rule}`;
  }

  // --- interaction ---
  function paint(event) {
    const rect = canvas.getBoundingClientRect();
    const x = (event.clientX - rect.left) * (canvas.width  / rect.width);
    const y = (event.clientY - rect.top)  * (canvas.height / rect.height);
    const c = Math.floor(x / N);
    const r = Math.floor(y / N);
    return { r: Math.min(ROWS - 1, Math.max(0, r)), c: Math.min(COLS - 1, Math.max(0, c)) };
  }

  let drawing = false;
  canvas.addEventListener("mousedown", (e) => {
    drawing = true;
    const { r, c } = paint(e);
    grid[r][c] = 1;
    draw();
  });
  canvas.addEventListener("mousemove", (e) => {
    if (!drawing) return;
    const { r, c } = paint(e);
    grid[r][c] = 1;
    draw();
  });
  window.addEventListener("mouseup", () => (drawing = false));
  canvas.addEventListener("touchstart", (e) => { e.preventDefault(); drawing = true; const t = e.touches[0]; const {r,c}=paint(t); grid[r][c]=1; draw(); });
  canvas.addEventListener("touchmove",  (e) => { e.preventDefault(); const t = e.touches[0]; const {r,c}=paint(t); grid[r][c]=1; draw(); });
  canvas.addEventListener("touchend",  () => (drawing = false));

  window.addEventListener("keydown", (e) => {
    if (e.code === "Space") { e.preventDefault(); togglePlay(); }
    else if (e.key === "r" || e.key === "R") { randomizeFill(); draw(); }
    else if (e.key === "c" || e.key === "C") { clearGrid(); draw(); }
  });

  function togglePlay() {
    running = !running;
    playBtn.textContent = running ? "Pause" : "Play";
    playBtn.classList.toggle("primary", running);
  }

  playBtn.addEventListener("click", togglePlay);
  $("step").addEventListener("click", () => { step(); draw(); });
  $("random").addEventListener("click", () => { randomizeFill(); draw(); });
  $("clear").addEventListener("click", () => { clearGrid(); draw(); });
  ruleSel.addEventListener("change", () => { rule = ruleSel.value; draw(); });

  // main loop
  let last = 0;
  function loop(t) {
    const interval = 1000 / speed.value;
    if (running && t - last >= interval) { last = t; step(); draw(); }
    requestAnimationFrame(loop);
  }

  // seed with a small classic glider on load
  gen = 0;
  const glider = [
    [1, 0], [2, 1], [0, 2], [1, 2], [2, 2],
  ];
  glider.forEach(([dr, dc]) => { grid[10 + dr][40 + dc] = 1; });

  draw();
  requestAnimationFrame(loop);
})();
</script>
</body>
</html>
