// Replicate the step logic to verify a blinker oscillates (period 2).
function makeGrid(rows, cols){return Array.from({length:rows},()=>new Uint8Array(cols));}
function countNeighbors(g,r,c,ROWS,COLS){let n=0;for(let dr=-1;dr<=1;dr++)for(let dc=-1;dc<=1;dc++){if(dr===0&&dc===0)continue;const rr=(r+dr+ROWS)%ROWS,cc=(c+dc+COLS)%COLS;n+=g[rr][cc];}return n;}
function step(grid,s,b,ROWS,COLS){const next=makeGrid(ROWS,COLS);for(let r=0;r<ROWS;r++)for(let c=0;c<COLS;c++){const n=countNeighbors(grid,r,c,ROWS,COLS),alive=grid[r][c]===1;next[r][c]=(alive?s.includes(n):b.includes(n))?1:0;}return next;}
// blinker: horizontal 3 cells
let g=makeGrid(5,5);
g[2][1]=1;g[2][2]=1;g[2][3]=1;
const s=[2,3],b=[3];
const g1=step(g,s,b,5,5);   // vertical
const g2=step(g1,s,b,5,5);
function cells(m){const o=[];for(let r=0;r<5;r++)for(let c=0;c<5;c++)if(m[r][c])o.push(r+','+c);return o.sort().join(' ');}
const c0=cells(g),c1=cells(g1),c2=cells(g2);
console.log('gen0:',c0);
console.log('gen1:',c1);
console.log('gen2:',c2);
console.log('oscillates (gen0==gen2):', c0===c2);
